using System;using System.IO;using System.Collections.Generic;
class SentenceBoundaryChecks {
 public class Captions {public List<Line> lines{get;set;}public double audio_duration{get;set;}}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Main(string[] args){try{Run(args);}catch(Exception ex){Console.WriteLine(ex.Message);Environment.Exit(1);}} static void Run(string[] args){int count=0;foreach(string file in Directory.GetFiles(Path.Combine(args[0],"assets/tavern/listening/real-exams"),"*.captions.json",SearchOption.AllDirectories)){var captionDoc=Engine.Json.Deserialize<Captions>(File.ReadAllText(file));var source=captionDoc.lines;var lines=ListeningCaptionIntegrity.Normalize(source,null);Check(lines.Count==source.Count,"caption normalization preserves corrected boundaries");for(int i=0;i<lines.Count;i++){long stop=SpellPracticeAudio.SentenceEndMs(lines,i);Check(stop>lines[i].start*1000,"positive clip");Check(stop<=Math.Round(captionDoc.audio_duration*1000),"stop stays inside recording duration");Check(stop>=Math.Round(lines[i].end*1000),"complete current sentence");Check(lines[i].playback_end+.001>=lines[i].end,"audited playback boundary loaded");Check(stop==Math.Round(lines[i].playback_end*1000),"uses recording boundary");if(i+1<lines.Count){long next=(long)Math.Round(lines[i+1].start*1000);Check(stop<=next,"never enters next sentence");}if(lines[i].text.Contains("beyond most students' budgets")&&file.Contains("cet6")&&file.Contains("2025_12_2")){Check(stop>=78562&&stop<78970,"reported budgets tail completes before next spoken hesitation");Check(lines[i+1].start>78.56,"Um/Ah interpolation no longer cuts budgets");}if(lines[i].text=="It cost them a pretty penny."&&file.Contains("cet6")&&file.Contains("2025_12_2")){Check(stop>=137047&&stop<137440,"penny tail completes before next Yeah/Now ASR substitution");}if(lines[i].text=="They have such a great variety."&&file.Contains("cet6")&&file.Contains("2025_12_2")){Check(stop>=96820&&stop<97719,"reported variety tail completes inside real inter-sentence pause");Check(lines[i+1].start>97.5,"following Yeah no longer clips preceding tail");}count++;}}var test=new List<Line>{new Line{start=0,end=1},new Line{start=1.15,end=2}};Check(SpellPracticeAudio.SentenceEndMs(test,0)==1150,"fallback retains sentence tail");test[1].start=1.03;Check(SpellPracticeAudio.SentenceEndMs(test,0)==1030,"fallback stops at next sentence");test[0].playback_end=1.02;Check(SpellPracticeAudio.SentenceEndMs(test,0)==1020,"explicit pause stop");test[0].end=1.2;Check(SpellPracticeAudio.SentenceEndMs(test,0)==1030,"overlapping input cannot enter next sentence");Console.WriteLine("PASS "+count+" sentence ends: recording-derived stops, caption normalization, reported budgets, variety and penny regressions, next sentence limits and overlapping input.");}
}
